<?php $this->assign('title', 'Auditoría | CatOps Admin'); ?>
<div class="d-flex justify-content-between gap-3 mb-4 page-heading"><div><h1 class="h2 mb-1">Auditoría</h1><p class="text-muted mb-0">Registro inmutable de eventos y acciones administrativas.</p></div></div>
<section class="card admin-card mb-4"><div class="card-body"><form class="row g-2" method="get"><div class="col-12 col-md-3"><input class="form-control" name="action" value="<?= h($filters['action']) ?>" placeholder="Acción"></div><div class="col-6 col-md-2"><select class="form-select" name="entity"><option value="">Entidad</option><?php foreach ($entities as $row): ?><?php if ($row->entity): ?><option value="<?= h($row->entity) ?>" <?= $filters['entity'] === $row->entity ? 'selected' : '' ?>><?= h($row->entity) ?></option><?php endif; ?><?php endforeach; ?></select></div><div class="col-6 col-md-2"><input class="form-control" type="number" name="user_id" value="<?= h($filters['user_id']) ?>" placeholder="ID usuario"></div><div class="col-6 col-md-2"><input class="form-control" type="date" name="from" value="<?= h($filters['from']) ?>"></div><div class="col-6 col-md-2"><input class="form-control" type="date" name="to" value="<?= h($filters['to']) ?>"></div><div class="col-12 col-md-1"><button class="btn btn-primary w-100">Filtrar</button></div></form></div></section>
<section class="card admin-card"><div class="table-wrap"><table class="table align-middle"><thead><tr><th>Fecha</th><th>Acción</th><th>Actor</th><th>Entidad</th><th>Datos</th></tr></thead><tbody><?php foreach ($pagination['items'] as $audit): ?><tr><td><?= h($audit->created) ?></td><td><strong><?= h($audit->action) ?></strong></td><td><?= h($audit->user->email ?? 'sistema') ?></td><td><?= h(($audit->entity ?: '—') . ($audit->entity_id ? ' #' . $audit->entity_id : '')) ?></td><td><details><summary class="small">Ver datos</summary><pre class="payload bg-light p-2 rounded mt-2 mb-0"><?= h(is_string($audit->data) ? $audit->data : json_encode($audit->data, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)) ?></pre></details></td></tr><?php endforeach; ?></tbody></table></div><div class="card-body"><?= $this->element('admin_pagination', compact('pagination')) ?></div></section>
